// The shapes that the status line reads.
// Claude Code sends the status object on stdin, and the subagent status line gets its own JSON.
// Each field is optional, because Claude Code can leave any field out.

import type { Paint } from "../color.ts";

/** One limit window. `used_percentage` is in percent, and `resets_at` is in seconds. */
export type LimitWindow = {
  used_percentage?: number;
  resets_at?: number | null;
};

/** The prompt cache of the main conversation, as Claude Code 2.1.301 gives it after the first response. */
export type PromptCache = {
  warm?: boolean;
  caching_observed?: boolean;
  expires_at?: number | null;
  recache_tokens_if_cold?: number | null;
};

/** The open pull request of the branch. `kind` is `mr` for a GitLab merge request. */
export type PullRequest = {
  number?: number;
  review_state?: string;
  kind?: string;
};

/** The status object that Claude Code sends on stdin. */
export type StatusInput = {
  cwd?: string;
  model?: { id?: string; display_name?: string };
  workspace?: { current_dir?: string; project_dir?: string };
  cost?: {
    total_cost_usd?: number;
    total_lines_added?: number;
    total_lines_removed?: number;
  };
  context_window?: {
    total_input_tokens?: number;
    context_window_size?: number;
    /** `null` before the first message. */
    used_percentage?: number | null;
  };
  prompt_cache?: PromptCache;
  pr?: PullRequest;
  effort?: { level?: string };
  thinking?: { enabled?: boolean };
  rate_limits?: {
    five_hour?: LimitWindow;
    seven_day?: LimitWindow;
    spend_limit?: LimitWindow;
  };
};

/** The branch, the changed files, and the commits ahead and behind of the working folder. */
export type GitState = {
  branch: string;
  dirty: number;
  ahead: number;
  behind: number;
};

/** A `git` call that failed, with the cause. It is not the same as a folder that is no repository. */
export type GitFault = { error: string };

/** The state of the active MiniSpec change, from its `tasks.md`. */
export type Change =
  /** No task yet: the change is in planning. */
  | { readonly name: string; readonly state: "planning" }
  /** Some task is open. `next` is the id of the first open task. */
  | {
      readonly name: string;
      readonly state: "open";
      readonly done: number;
      readonly total: number;
      readonly next: string;
    }
  /** Each task is checked. The change is ready for review and archive. */
  | { readonly name: string; readonly state: "done"; readonly total: number }
  /** `tasks.md` could not be read. */
  | { readonly name: string; readonly state: "error" };

/** Everything that a segment may read. `now` is in milliseconds, and `paint` has the styles. */
export type Status = {
  input: StatusInput;
  folder: string;
  git: GitState | GitFault | null;
  change: Change | null;
  now: number;
  paint: Paint;
  /** True when the `compaction` option is `built-in`, so the context nears the compaction and not a handoff. */
  compaction: boolean;
  /** True when the times use the countdown of 1.0.0, such as `3h12m`, in place of the clock. */
  compact: boolean;
};

/** One running subagent, as the subagent status line gets it. */
export type Task = {
  id?: string;
  name?: string;
  agentType?: string;
  status?: string;
  description?: string;
  startTime?: number | string;
  model?: string;
  effort?: string;
  contextWindowSize?: number;
  tokenCount?: number;
};

/** The JSON that the subagent status line gets on stdin. */
export type SubagentInput = { columns?: number; tasks?: Task[] };

/** One output row of the subagent status line. */
export type TaskRow = { id: string; content: string };
